const I18N = {
  t(lang, key, vars) {
    let s = (TEXTS[lang] && TEXTS[lang][key]) ?? TEXTS.en[key] ?? key;
    if (vars) for (const k of Object.keys(vars)) s = s.split(`{${k}}`).join(String(vars[k]));
    return s;
  },
  apply(lang, root = document) {
    document.documentElement.lang = lang;
    for (const el of root.querySelectorAll('[data-i18n]')) el.textContent = I18N.t(lang, el.getAttribute('data-i18n'));
    for (const el of root.querySelectorAll('[data-i18n-title]')) el.title = I18N.t(lang, el.getAttribute('data-i18n-title'));
  }
};
